{
  "name": "@project-osrm/osrm",
  "version": "26.9.0",
  "private": false,
  "type": "module",
  "description": "The Open Source Routing Machine is a high performance routing engine written in C++ designed to run on OpenStreetMap data.",
  "dependencies": {
    "@mapbox/node-pre-gyp": "^2.0.3",
    "seedrandom": "^3.0.5"
  },
  "scripts": {
    "lint": "npx eslint features/",
    "test": "./scripts/cucumber_test_matrix.sh",
    "clean": "rm -rf test/cache",
    "docs": "./scripts/build_api_docs.sh",
    "docs:dev": "vitepress dev docs",
    "regenerate-fbresult": "./scripts/regenerate_fbresult_js.sh",
    "install": "node-pre-gyp install --fallback-to-build=false || ./scripts/node_install.sh",
    "nodejs-tests": "make -C test/data && ./lib/binding_napi_v8/osrm-datastore test/data/ch/monaco.osrm && node test/nodejs/index.js | tap-spec",
    "prepare": "husky"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/Project-OSRM/osrm-backend.git"
  },
  "author": "Project OSRM Team",
  "license": "BSD-2-Clause",
  "bugs": {
    "url": "https://github.com/Project-OSRM/osrm-backend/issues"
  },
  "homepage": "https://github.com/Project-OSRM/osrm-backend",
  "engines": {
    "node": "^20.17.0 || >=22.9.0"
  },
  "devDependencies": {
    "@babel/core": "^8.0.1",
    "@babel/preset-env": "^8.0.2",
    "@babel/preset-react": "^8.0.1",
    "@cucumber/cucumber": "^13.0.0",
    "@mapbox/polyline": "1.2.1",
    "@turf/turf": "^7.3.4",
    "ansi-escape-sequences": "6.2.4",
    "chalk": "^5.6.2",
    "cheap-ruler": "^4.0.0",
    "cmake-js": "^8.0.0",
    "command-line-args": "^6.0.2",
    "command-line-usage": "^7.0.4",
    "csv-stringify": "^6.6.0",
    "eslint": "^10.0.0",
    "express": "^5.2.1",
    "fast-xml-parser": "^5.5.11",
    "flatbuffers": "^25.9.23",
    "husky": "^9.1.7",
    "jsonpath-plus": "^10.4.0",
    "lint-staged": "^17.0.7",
    "node-addon-api": "^8.5.0",
    "strip-ansi": "^7.1.0",
    "tap-spec": "^2.2.2",
    "tape": "5.10.2",
    "vitepress": "^1.6.4",
    "wait-on": "^9.0.4",
    "xml2js": "^0.6.0",
    "xmlbuilder": "15.1.1"
  },
  "main": "lib/index.js",
  "binary": {
    "napi_versions": [
      8
    ],
    "module_name": "node_osrm",
    "module_path": "./lib/binding_napi_v{napi_build_version}/",
    "host": "https://github.com",
    "remote_path": "./Project-OSRM/osrm-backend/releases/download/v{version}/",
    "package_name": "{module_name}-v{version}-{napi_build_version}-{platform}-{arch}-{configuration}.tar.gz"
  },
  "lint-staged": {
    "features/**/*.js": [
      "node --check",
      "eslint --fix"
    ]
  },
  "publishConfig": {
    "access": "public"
  },
  "overrides": {
    "vitepress": {
      "vite": "6.4.3"
    },
    "tap-spec": {
      "pretty-ms": "3.2.0"
    },
    "esbuild": "0.27.2",
    "eslint": {
      "ajv": "^6"
    },
    "glob": "^13.0.0",
    "ajv": ">=6.14.0",
    "minimatch": ">=10.2.1",
    "tar": ">=7.5.10"
  },
  "allowScripts": {
    "esbuild@0.27.2": true,
    "fsevents@2.3.3": true
  }
}
